55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	/**
65	 * Insurance values are distinct from base premiums: they size the payout cap,
66	 * not the price. Component block discounts affect the premium only, never the
67	 * insurance sum, so this table is always applied per individual item.
68	 */
69	const INSURANCE_VALUES: Record<string, number> = {
70	  sword: 1000,
71	  amulet: 600,
72	  staff: 800,
73	  potion: 400,
74	  rune: 250,
75	  moonstone: 250,
76	};
77	
78	const DEDUCTIBLE_PER_DAMAGE = 100;
79	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
80	
81	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
82	const PROCESSING_FEE = 5;
83	
84	const HUNDRED = 100;
85	
86	/**
87	 * The value of a percentage of an amount. Modifiers are summed as separate
88	 * amounts rather than compounded, so each is computed against its own base:
89	 * a cursed sword is 100 + 50 % of 100 + 10 % of 100, not 100 × 1.5 × 1.1.
90	 *
91	 * Multiplies before dividing, keeping the percentage an integer ratio rather
92	 * than a decimal factor: 100 * 1.1 === 110.00000000000001 in binary floating
93	 * point, which would round the wrong way. Intermediates stay exact and only
94	 * the final premium is rounded.
95	 */
96	const percentOf = (amount: number, percent: number): number =>
97	  (amount * percent) / HUNDRED;
98	
99	/** Premiums are rounded up — in the MHPCO's favour. */
100	const roundPremium = (amount: number): number => Math.ceil(amount);
101	
102	/**
103	 * Payouts are rounded DOWN, the mirror of `roundPremium`'s ceiling. The two
104	 * directions look inconsistent side by side but express one rule: the office
105	 * keeps the fraction either way, charging the most and paying the least that
106	 * the amount allows.
107	 */
108	const roundPayout = (amount: number): number => Math.floor(amount);
109	
110	const basePremiumOfType = (type: string): number => {
111	  const basePremium = BASE_PREMIUMS[type];
112	  if (basePremium === undefined) {
113	    // The spec rejects a quote containing an unknown item type outright, but
114	    // no active test pins the error behaviour yet. Fail loudly rather than
115	    // silently pricing an unknown item at zero, which the spec contradicts.
116	    throw new Error(`Unknown item type: ${type}`);
117	  }
118	  return basePremium;
119	};
120	
121	/** Component types are sold individually or as a block of alike pieces. */
122	const COMPONENT_TYPES = ["rune", "moonstone"];
123	const COMPONENT_BLOCK_SIZE = 3;
124	const COMPONENT_BLOCK_PREMIUM = 60;
125	
126	const countByType = (items: Item[]): Map<string, number> => {
127	  const counts = new Map<string, number>();
128	  for (const item of items) {
129	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
130	  }
131	  return counts;
132	};
133	
134	/**
135	 * Base premium for a group of alike items. A block rate applies only when a
136	 * component type appears exactly COMPONENT_BLOCK_SIZE times — blocks do not
137	 * repeat, so 4 runes cost 4 singles rather than a block plus a single.
138	 */
139	const basePremiumOfGroup = (type: string, count: number): number => {
140	  if (COMPONENT_TYPES.includes(type) && count === COMPONENT_BLOCK_SIZE) {
141	    return COMPONENT_BLOCK_PREMIUM;
142	  }
143	  return count * basePremiumOfType(type);
144	};
145	
146	const CURSE_SURCHARGE_PERCENT = 50;
147	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
148	const HIGH_ENCHANTMENT_MIN_LEVEL = 5;
149	
150	/**
151	 * Whether an item carries an enchantment at or above the surcharge threshold.
152	 * Components (runes, moonstones) have no enchantment field at all; an absent
153	 * enchantment is not a level of 0, it is the absence of the property, and so
154	 * never qualifies. Stated as an explicit undefined check rather than a numeric
155	 * default so the reason reads as "unenchanted", not "enchanted to zero".
156	 */
157	const isHighlyEnchanted = (item: Item): boolean =>
158	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_MIN_LEVEL;
159	
160	/**
161	 * Item-specific surcharges are a percentage of the affected item's OWN base
162	 * premium, not of the policy total. They are summed alongside the policy-wide
163	 * modifiers rather than compounded with them, so an item that is both cursed
164	 * and highly enchanted carries base + 50 % of base + 30 % of base.
165	 *
166	 * KNOWN GAP: basePremiumOfType gives the item's standalone base, which differs
167	 * from its share of a component block — a rune in a block of 3 is charged 20,
168	 * not 25, so a cursed or highly enchanted rune inside a block would surcharge
169	 * against 25. This affects both surcharge terms, not just the curse. Left as
170	 * is deliberately: the spec defines neither cursed nor enchanted components,
171	 * gives no rule for apportioning a block rate across its pieces, and no test
172	 * pins the behaviour. Resolve it when a test forces a choice, not before.
173	 */
174	const itemSurchargeOf = (item: Item): number => {
175	  const itemBase = basePremiumOfType(item.type);
176	  const curseSurcharge =
177	    item.cursed === true ? percentOf(itemBase, CURSE_SURCHARGE_PERCENT) : 0;
178	  const enchantmentSurcharge = isHighlyEnchanted(item)
179	    ? percentOf(itemBase, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
180	    : 0;
181	  return curseSurcharge + enchantmentSurcharge;
182	};
183	
184	const LOYALTY_DISCOUNT_PERCENT = 20;
185	const LOYALTY_MIN_YEARS = 2;
186	
187	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
188	
189	/**
190	 * Quotes are numbered from this ordinal; every quote after it is a follow-up
191	 * contract. The ordinal counts QUOTE steps only — claim steps interleave with
192	 * quotes in a scenario and must not advance the contract count.
193	 */
194	const FIRST_QUOTE_ORDINAL = 0;
195	
196	/** Long-standing customers qualify from exactly LOYALTY_MIN_YEARS onwards. */
197	const isLongStanding = (customer: Customer): boolean =>
198	  customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS;
199	
200	/** Every contract after the customer's first one in the scenario. */
201	const isFollowUpContract = (quoteOrdinal: number): boolean =>
202	  quoteOrdinal > FIRST_QUOTE_ORDINAL;
203	
204	/** Policy base premium: every group's base, before any modifier. */
205	const policyBaseOf = (items: Item[]): number =>
206	  [...countByType(items)].reduce(
207	    (total, [type, count]) => total + basePremiumOfGroup(type, count),
208	    0,
209	  );
210	
211	const itemSurchargesOf = (items: Item[]): number =>
212	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
213	
214	/**
215	 * The net of the policy-wide modifiers: surcharges positive, discounts
216	 * negative. Each is a percentage of the POLICY base and they are summed, never
217	 * compounded — a long-standing customer's first insurance is +10 % and -20 % of
218	 * the same base, a net -10 %, not 1.1 × 0.8.
219	 */
220	const policyModifiersOf = (
221	  policyBase: number,
222	  customer: Customer,
223	  quoteOrdinal: number,
224	): number => {
225	  const firstInsuranceSurcharge = percentOf(
226	    policyBase,
227	    FIRST_INSURANCE_SURCHARGE_PERCENT,
228	  );
229	  const loyaltyDiscount = isLongStanding(customer)
230	    ? percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
231	    : 0;
232	  const followUpDiscount = isFollowUpContract(quoteOrdinal)
233	    ? percentOf(policyBase, FOLLOW_UP_DISCOUNT_PERCENT)
234	    : 0;
235	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
236	};
237	
238	const quoteResult = (
239	  items: Item[],
240	  customer: Customer,
241	  quoteOrdinal: number,
242	): QuoteResult => {
243	  const policyBase = policyBaseOf(items);
244	  const premium =
245	    policyBase +
246	    itemSurchargesOf(items) +
247	    policyModifiersOf(policyBase, customer, quoteOrdinal) +
248	    PROCESSING_FEE;
249	  return { premium: roundPremium(premium) };
250	};
251	
252	/** A quote step's policy, carried forward so later claims can draw on it. */
253	interface Policy {
254	  items: Item[];
255	  remainingCap: number;
256	}
257	
258	const policyFor = (items: Item[]): Policy => {
259	  const insuranceSum = items.reduce(
260	    (total, item) => total + (INSURANCE_VALUES[item.type] ?? 0),
261	    0,
262	  );
263	  return {
264	    items,
265	    remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum,
266	  };
267	};
268	
269	const HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL = 8;
270	const HIGH_ENCHANTMENT_CLAUSE_PERCENT = 50;
271	
272	/**
273	 * The damaged item, located by type. A damage entry names a TYPE, not a
274	 * particular item, so a policy holding two swords of different enchantments is
275	 * ambiguous; the spec offers no tie-break, so the first match wins.
276	 */
277	const damagedItem = (damage: Damage, items: Item[]): Item | undefined =>
278	  items.find((item) => item.type === damage.itemType);
279	
280	/**
281	 * One damage event. A special clause reduces the reimbursed amount BEFORE the
282	 * deductible is taken: an item enchanted to HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL
283	 * or above is reimbursed at half, so 1000 becomes 500 and then 400 — not
284	 * (1000 - 100) halved.
285	 *
286	 * DRAGON MATERIAL, deliberately unexpressed. The spec states a second clause —
287	 * damage to dragon-material items is FULLY reimbursed — which this function
288	 * never mentions. That is considered, not overlooked. Full reimbursement is
289	 * already the default path when no clause fires, so a dragon branch returning
290	 * damage.amount would be a branch no test could ever distinguish from its own
291	 * absence. The three spec cases pass unchanged: dragon/ench 8/1000 -> 400,
292	 * dragon/ench 5/800 -> 700, dragon/ench 9/1000 -> 400.
293	 *
294	 * The clauses also do not conflict in the way "both apply" suggests. Where an
295	 * item is both dragon and enchanted >= 8, the spec has the 50 % rule WIN — so
296	 * the enchantment check above is not merely first, it is correct to be the
297	 * only check. Should a later rule ever make full reimbursement differ from the
298	 * default (a cap interaction, say), this clause must become explicit.
299	 */
300	const payoutForDamage = (damage: Damage, items: Item[]): number => {
301	  const item = damagedItem(damage, items);
302	  const enchantment = item?.enchantment;
303	  const reimbursed =
304	    enchantment !== undefined &&
305	    enchantment >= HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL
306	      ? percentOf(damage.amount, HIGH_ENCHANTMENT_CLAUSE_PERCENT)
307	      : damage.amount;
308	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
309	};
310	
311	/**
312	 * A policy pays at most what its cap has left, so a claim beyond the cap is
313	 * reduced to the remainder and an exhausted policy pays nothing — the cap lands
314	 * on 0 rather than going negative. The spec's own phrasing: "the desired 1400 G
315	 * is reduced to the remaining cap".
316	 */
317	const reducedToRemainingCap = (desired: number, remainingCap: number): number =>
318	  Math.min(desired, remainingCap);
319	
320	/**
321	 * A claim's effect on its policy: what is paid now and what the policy has
322	 * left afterwards. Pure — the caller is responsible for storing the new
323	 * remaining cap, so the arithmetic can be read without tracing who mutated
324	 * what.
325	 *
326	 * The reduction to the cap happens on the DESIRED total, before the result is
327	 * reported. A later rounding rule must therefore apply to the already-reduced
328	 * payout: an unreduced desired payout can be fractional, and rounding ahead of
329	 * the reduction would misreport the remaining cap.
330	 */
331	const claimOutcome = (incident: Incident, policy: Policy): ClaimResult => {
332	  const desired = incident.damages.reduce(
333	    (total, damage) => total + payoutForDamage(damage, policy.items),
334	    0,
335	  );
336	  const payout = roundPayout(
337	    reducedToRemainingCap(desired, policy.remainingCap),
338	  );
339	  return { payout, remainingCap: policy.remainingCap - payout };
340	};
341	
342	/**
343	 * Where a step sits in the scenario walk. The two ordinals are genuinely
344	 * different facts and must not be collapsed: `index` is the step's own
345	 * zero-based position, which is how a later claim names its policy, while
346	 * `quoteOrdinal` counts QUOTE steps only. In [quote, claim, quote] the last
347	 * step has index 2 but quote ordinal 1 — using either in place of the other
348	 * would misprice the follow-up discount.
349	 */
350	interface StepPosition {
351	  index: number;
352	  quoteOrdinal: number;
353	}
354	
355	/** The mutable state carried along one scenario: the policies quotes create. */
356	interface ScenarioWalk {
357	  customer: Customer;
358	  policies: Map<number, Policy>;
359	}
360	
361	const runStep = (
362	  step: Step,
363	  position: StepPosition,
364	  walk: ScenarioWalk,
365	): StepResult => {
366	  if (step.op === "quote") {
367	    walk.policies.set(position.index, policyFor(step.items));
368	    return quoteResult(step.items, walk.customer, position.quoteOrdinal);
369	  }
370	  const policy = walk.policies.get(step.policy);
371	  if (policy === undefined) {
372	    throw new Error(`No policy created by step ${step.policy}`);
373	  }
374	  const outcome = claimOutcome(step.incident, policy);
375	  policy.remainingCap = outcome.remainingCap;
376	  return outcome;
377	};
378	
379	export const runScenario = (scenario: Scenario): ScenarioResults => {
380	  const walk: ScenarioWalk = {
381	    customer: scenario.customer,
382	    policies: new Map<number, Policy>(),
383	  };
384	  let quoteOrdinal = FIRST_QUOTE_ORDINAL;
385	  const results = scenario.steps.map((step, index) => {
386	    const result = runStep(step, { index, quoteOrdinal }, walk);
387	    if (step.op === "quote") quoteOrdinal += 1;
388	    return result;
389	  });
390	  return { results };
391	};
392

