/** Premiums are rounded up — in the MHPCO's favour. */
const roundPremium = (amount: number): number => Math.ceil(amount);

/**
 * Payouts are rounded DOWN, the mirror of `roundPremium`'s ceiling. The two
 * directions look inconsistent side by side but express one rule: the office
 * keeps the fraction either way, charging the most and paying the least that
 * the amount allows.
 */
const roundPayout = (amount: number): number => Math.floor(amount);
